package sfz.enc.l05.demo

import kotlin.random.Random

/**
 * 10,000 orders run charge -> reserve -> ship, and the process sometimes dies. Each step has two places to die:
 * before its side effect, and after the side effect but before the program has written down that it happened.
 * Four ways to recover, and what each leaves behind. Plain Kotlin, no Temporal.
 */

private const val ORDERS = 10_000
private const val CRASH_CHANCE = 0.005 // at each of the 6 points
private val STEPS = listOf("charge", "reserve", "ship")

private class Outcome {
    var charges = 0; var reservations = 0; var parcels = 0
    var chargedNotShipped = 0; var doubleCharged = 0
}

private enum class Recovery { NONE, RESTART_FROM_TOP, STATUS_COLUMN, STATUS_COLUMN_AND_KEYS }

private fun run(recovery: Recovery, seed: Int): Outcome {
    val rnd = Random(seed)
    val out = Outcome()
    repeat(ORDERS) { n ->
        var status = 0 // the status column: how many steps are recorded as done
        val keysSeen = HashSet<String>() // the bank's idempotency keys, for the last strategy
        var chargesForOrder = 0
        var finished = false
        var attempts = 0
        while (!finished && attempts < 10) {
            attempts++
            var crashed = false
            val from = if (recovery == Recovery.STATUS_COLUMN || recovery == Recovery.STATUS_COLUMN_AND_KEYS) status else 0
            for (i in from until STEPS.size) {
                if (rnd.nextDouble() < CRASH_CHANCE) { crashed = true; break } // died before the side effect
                when (STEPS[i]) { // the side effect
                    "charge" -> {
                        val key = "order-$n/charge"
                        if (recovery != Recovery.STATUS_COLUMN_AND_KEYS || keysSeen.add(key)) { out.charges++; chargesForOrder++ }
                    }
                    "reserve" -> out.reservations++
                    "ship" -> out.parcels++
                }
                if (rnd.nextDouble() < CRASH_CHANCE) { crashed = true; break } // died after it, before recording it
                status = i + 1 // UPDATE orders SET status = ... (one local transaction)
            }
            if (!crashed) finished = true
            if (recovery == Recovery.NONE) break // nobody comes back for it
        }
        if (chargesForOrder > 0 && !finished) out.chargedNotShipped++
        if (chargesForOrder > 1) out.doubleCharged++
    }
    return out
}

fun main() {
    println("$ORDERS orders; at each of 6 points the process dies with probability $CRASH_CHANCE")
    println("%-26s %8s %18s %14s".format("recovery", "charges", "charged, unshipped", "double charges"))
    for (r in Recovery.entries) {
        val o = run(r, seed = 7)
        println("%-26s %8d %18d %14d".format(r.name.lowercase().replace('_', ' '), o.charges, o.chargedNotShipped, o.doubleCharged))
    }
}

package sfz.enc.l05.demo

/**
 * The first charge attempt moves the money and then dies before reporting back. Temporal retries it.
 * Run twice: against a bank that ignores idempotency keys, and against one that honours them.
 */
fun main() {
    quiet()
    for (honorKeys in listOf(false, true)) {
        newEnv().use { env ->
            val bank = FakeBank(honorKeys)
            val worker = startWorker(env.workflowClient, "worker-1", OrderV1::class.java, StepsImpl(bank, crashAfterCharge = true))
            val result = startOrder(env.workflowClient, "order-7").getResult(String::class.java)
            println("bank honours keys=$honorKeys: $result, charge activity ran ${worker.steps.runs("charge")}x, card charged ${bank.charges.get()}x")
            if (!honorKeys) {
                env.workflowClient.fetchHistory("order-7").events
                    .filter { it.hasActivityTaskScheduledEventAttributes() || it.hasActivityTaskStartedEventAttributes() || it.hasActivityTaskCompletedEventAttributes() }
                    .take(3)
                    .forEach { println("    " + describe(it)) }
            }
            worker.kill()
        }
    }
}

package sfz.enc.l05.demo

import io.temporal.testing.WorkflowReplayer

/**
 * Records the history of an order that ran on version 1, then replays it against two versions of the new code,
 * the way a CI job replays histories saved from production before a deploy.
 */
fun main() {
    quiet()
    val history = newEnv().use { env ->
        val worker = startWorker(env.workflowClient, "worker-1", OrderV1::class.java, StepsImpl(FakeBank(true)))
        startOrder(env.workflowClient, "order-9").getResult(String::class.java)
        worker.kill()
        env.workflowClient.fetchHistory("order-9")
    }
    println("a version-1 history with ${history.events.size} events")

    for (code in listOf(OrderV2Naive::class.java, OrderV2::class.java)) {
        try {
            WorkflowReplayer.replayWorkflowExecution(history, code)
            println("${code.simpleName}: replays cleanly")
        } catch (e: Exception) {
            // the replayer wraps the error; dig out the NonDeterministicException's own message
            val text = generateSequence<Throwable>(e) { it.cause }.joinToString(" ") { it.message ?: "" }
            println("${code.simpleName}: " + text.substringAfter("error=").substringBefore(" {WorkflowTaskStartedEventId").replace("\n", ""))
        }
    }
}

