val stuck = jdbc.query("""
    SELECT id, status FROM orders
    WHERE status <> 'SHIPPED' AND updated_at < now() - interval '5 minutes'
    FOR UPDATE SKIP LOCKED LIMIT 100""")
for (o in stuck) when (o.status) {
    "NEW" -> { bank.charge("${o.id}/charge", o); setStatus(o, "CHARGED") }
    "CHARGED" -> try {
        warehouse.reserve("${o.id}/reserve", o); setStatus(o, "RESERVED")
    } catch (e: OutOfStock) { setStatus(o, "REFUNDING") }
    "REFUNDING" -> { bank.refund("${o.id}/refund", o); setStatus(o, "REFUNDED") }
    "RESERVED" -> if (pickupDue(o)) { courier.ship("${o.id}/ship", o); setStatus(o, "SHIPPED") }
}

